package dijkstra

import "testing"

func TestSimple(t *testing.T) {
	g := NewGraph(4)
	g.AddEdge(0, 1, 1)
	g.AddEdge(0, 2, 4)
	g.AddEdge(1, 2, 2)
	g.AddEdge(1, 3, 5)
	g.AddEdge(2, 3, 1)
	dist := g.Dijkstra(0)
	if dist[3] != 4 {
		t.Errorf("want 4, got %d", dist[3])
	}
}

func TestDirectSource(t *testing.T) {
	g := NewGraph(3)
	g.AddEdge(0, 1, 10)
	g.AddEdge(0, 2, 3)
	g.AddEdge(2, 1, 2)
	dist := g.Dijkstra(0)
	if dist[1] != 5 {
		t.Errorf("want 5, got %d", dist[1])
	}
	if dist[2] != 3 {
		t.Errorf("want 3, got %d", dist[2])
	}
}

func TestSingleNode(t *testing.T) {
	g := NewGraph(1)
	dist := g.Dijkstra(0)
	if dist[0] != 0 {
		t.Errorf("want 0, got %d", dist[0])
	}
}

func TestUnreachable(t *testing.T) {
	const INF = 1<<62 - 1
	g := NewGraph(3)
	g.AddEdge(0, 1, 1)
	dist := g.Dijkstra(0)
	if dist[2] != INF {
		t.Errorf("want INF, got %d", dist[2])
	}
}

func TestMultiPath(t *testing.T) {
	g := NewGraph(5)
	g.AddEdge(0, 1, 10)
	g.AddEdge(0, 2, 1)
	g.AddEdge(2, 3, 1)
	g.AddEdge(3, 1, 1)
	g.AddEdge(1, 4, 1)
	dist := g.Dijkstra(0)
	if dist[4] != 4 {
		t.Errorf("want 4 (path 0->2->3->1->4), got %d", dist[4])
	}
}

